using System;
using System.Collections.Generic;
using System.Linq;
using System.Globalization;
using Autodesk.AutoCAD.DatabaseServices;
using MedGas2024.Core;
namespace MedGas2024.Engine
{
    public sealed class LegacyMapPlan
    {
        public string CatalogState, Signature, Summary;public readonly List<BatchPreviewRow> Preview=new List<BatchPreviewRow>();
        public readonly List<LegacyMapAction> Actions=new List<LegacyMapAction>();public readonly Dictionary<ObjectId,string> LayerTypes=new Dictionary<ObjectId,string>();
    }
    public sealed class LegacyMapAction
    {
        public string Source, TargetType;public ObjectId SourceId,TargetLayer;public bool Create,CopySourceToExisting;public readonly List<ObjectId> Objects=new List<ObjectId>();public readonly List<ObjectId> AffectedLayers=new List<ObjectId>();
    }
    public static class LegacyMapping
    {
        public static LegacyMapCatalog Read(Database db)
        {
            var snapshot=LabelService.Read(db);var suggestions=LegacyRNames.Read(db);var result=new LegacyMapCatalog{Fingerprint=snapshot.Fingerprint};
            using(var tr=db.TransactionManager.StartOpenCloseTransaction())
            {
                var layers=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);foreach(ObjectId id in layers){var layer=(LayerTableRecord)tr.GetObject(id,OpenMode.ForRead);if(!layer.IsDependent)result.Layers.Add(layer.Name);}
                var types=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead);foreach(ObjectId id in types){var type=(LinetypeTableRecord)tr.GetObject(id,OpenMode.ForRead);if(!type.IsDependent&&id!=db.ByLayerLinetype&&id!=db.ByBlockLinetype)result.Types.Add(type.Name);}
            }
            result.Layers.Sort(StringComparer.CurrentCultureIgnoreCase);result.Types.Sort(StringComparer.CurrentCultureIgnoreCase);
            foreach(var suggested in suggestions){var members=snapshot.Members.Where(x=>String.Equals(x.Type,suggested.Before,StringComparison.OrdinalIgnoreCase)).ToList();result.Rows.Add(new LegacyMapRow{Source=suggested.Before,Label=suggested.Label,Count=members.Count,CurrentLayers=String.Join(", ",members.Select(x=>x.Layer).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x)),TargetLayer=LegacyMapCatalog.KeepLayer,TargetType=suggested.Ready?suggested.After:"",State=suggested.State});}
            foreach(var def in snapshot.Definitions.Where(d=>DensityMath.IsMrT(d.LinetypeName)&&RNameRules.OldName(d.LinetypeName)&&!result.Rows.Any(r=>String.Equals(r.Source,d.LinetypeName,StringComparison.OrdinalIgnoreCase)))){var members=snapshot.Members.Where(x=>String.Equals(x.Type,def.LinetypeName,StringComparison.OrdinalIgnoreCase)).ToList();if(members.Count>0)result.Rows.Add(new LegacyMapRow{Source=def.LinetypeName,Label=def.Text,Count=members.Count,CurrentLayers=String.Join(", ",members.Select(x=>x.Layer).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x)),TargetLayer=LegacyMapCatalog.KeepLayer,TargetType="",State="Chọn layer và tên nét chuẩn thủ công; cần xem trước."});}return result;
        }
        public static LegacyMapPlan Inspect(Database db,IEnumerable<LegacyMapRow> requested,string expectedCatalog)
        {
            var rows=requested.Where(r=>r.Use).ToList();if(rows.Count==0)throw new ArgumentException("Tích và chọn đích cho ít nhất một dòng.");if(rows.GroupBy(r=>r.Source,StringComparer.OrdinalIgnoreCase).Any(g=>g.Count()>1))throw new ArgumentException("Một nét nguồn không được ánh xạ nhiều lần.");var catalog=LabelService.Read(db);if(expectedCatalog!=null&&catalog.Fingerprint!=expectedCatalog)throw new InvalidOperationException("Bản vẽ đã đổi từ khi mở; đóng cửa sổ và mở lại để kiểm tra.");var plan=new LegacyMapPlan{CatalogState=catalog.Fingerprint};var layerTypes=new Dictionary<ObjectId,string>();var newTypes=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var overwrittenTypes=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var signature=new List<string>{catalog.Fingerprint};var typeIds=new List<ObjectId>();using(var scan=db.TransactionManager.StartOpenCloseTransaction()){var all=(LinetypeTable)scan.GetObject(db.LinetypeTableId,OpenMode.ForRead);foreach(ObjectId id in all)typeIds.Add(id);}var relative=RelativeTypeProbe.Read(db,typeIds);
            using(var tr=db.TransactionManager.StartOpenCloseTransaction())
            {
                var types=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead);var layers=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);var blocks=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);
                foreach(var row in rows)
                {
                    string source=(row.Source??"").Trim(),target=(row.TargetType??"").Trim(),layerName=(row.TargetLayer??"").Trim();if(!DensityMath.IsMrT(source)||!RNameRules.OldName(source)||!types.Has(source))throw new InvalidOperationException("Nét nguồn không còn hợp lệ: "+source);if(String.IsNullOrWhiteSpace(target))throw new ArgumentException("Chọn hoặc nhập linetype đích cho "+source+".");try{SymbolUtilityServices.ValidateSymbolName(target,false);}catch(Autodesk.AutoCAD.Runtime.Exception){throw new ArgumentException("Tên linetype đích không hợp lệ: "+target);}
                    if(String.Equals(source,target,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Linetype đích phải khác tên mã nguồn: "+source);if(RNameRules.OldName(target))throw new ArgumentException("Chọn tên linetype dễ đọc, không chọn một nét mã làm đích.");var src=(LinetypeTableRecord)tr.GetObject(types[source],OpenMode.ForRead);var srcDef=LabelService.Definition(src,tr);bool sourceR;if(!srcDef.Editable||!relative.TryGetValue(src.ObjectId,out sourceR)||!sourceR||src.ShapeIsUcsOrientedAt(1)||Math.Abs(src.ShapeRotationAt(1))>1e-10)throw new InvalidOperationException("Nét nguồn "+source+" không phải dạng chữ ba thành phần R=0 được hỗ trợ.");var members=catalog.Members.Where(x=>String.Equals(x.Type,source,StringComparison.OrdinalIgnoreCase)).ToList();if(members.Count==0)throw new InvalidOperationException("Không còn đường trực tiếp dùng nét "+source);if(members.Any(x=>x.Locked||x.Linked))throw new InvalidOperationException("Nét "+source+" có đường trên Layer khóa hoặc nhãn liên kết cũ. Mở khóa hoặc xử lý nhãn trước; chưa ghi nhóm này.");
                    string targetBefore="";bool create=!types.Has(target);if(create){string owner;if(newTypes.TryGetValue(target,out owner)&&!String.Equals(owner,source,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Hai nét nguồn cùng muốn tạo "+target+". Hãy chọn một nguồn chuẩn.");newTypes[target]=source;}
                    else{var dst=(LinetypeTableRecord)tr.GetObject(types[target],OpenMode.ForRead);bool targetR;if(!relative.TryGetValue(dst.ObjectId,out targetR)||!targetR)throw new InvalidOperationException("Nét đích chưa phải R; chọn nét R hoặc tên mới.");if(dst.IsDependent||dst.ObjectId==db.ByLayerLinetype||dst.ObjectId==db.ByBlockLinetype||dst.ObjectId==db.ContinuousLinetype)throw new InvalidOperationException("Không thể dùng linetype đích phụ thuộc/Xref hoặc ByLayer/ByBlock.");var dstDef=LabelService.Definition(dst,tr);targetBefore=dstDef.Text;if(!dstDef.Editable)throw new InvalidOperationException("Nét đích không có mẫu chữ ba thành phần được hỗ trợ: "+target);if(!String.Equals(LabelRules.Canonical(srcDef.Text),LabelRules.Canonical(dstDef.Text),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Chữ của nét đích "+target+" ["+dstDef.Text+"] khác chữ nguồn ["+srcDef.Text+"]. Hãy chọn đúng nét hoặc nhập tên mới.");if(row.CopySourceToExisting){if(!LabelService.CanRestoreLegacyR(src,tr))throw new InvalidOperationException("Nét nguồn thiếu dấu xác nhận R hợp lệ. Hãy nhập tên nét mới để sao chép, hoặc kiểm tra nguồn trước.");string prior;if(overwrittenTypes.TryGetValue(target,out prior)&&!String.Equals(prior,source,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Nhiều nét nguồn muốn ghi đè cùng một nét đích: "+target);overwrittenTypes[target]=source;}else{if(!dstDef.Editable||dst.ShapeIsUcsOrientedAt(1)||Math.Abs(dst.ShapeRotationAt(1))>1e-10)throw new InvalidOperationException("Nét đích "+target+" chưa có định dạng R=0 được hỗ trợ; chọn sao chép R nguồn, chọn nét R khác hoặc nhập tên mới.");}signature.Add("T|"+target+"|"+dstDef.Fingerprint);}
                    bool keep=String.IsNullOrEmpty(layerName)||layerName==LegacyMapCatalog.KeepLayer;ObjectId destLayer=ObjectId.Null;if(!keep){if(!layers.Has(layerName))throw new InvalidOperationException("Layer đích chưa có trong DWG: "+layerName+". Hãy tạo Layer trước hoặc chọn Layer hiện có.");var layer=(LayerTableRecord)tr.GetObject(layers[layerName],OpenMode.ForRead);if(layer.IsDependent||layer.IsLocked)throw new InvalidOperationException("Layer đích bị khóa hoặc phụ thuộc Xref: "+layerName);destLayer=layer.ObjectId;}
                    var action=new LegacyMapAction{Source=source,SourceId=src.ObjectId,TargetLayer=destLayer,TargetType=target,Create=create,CopySourceToExisting=!create&&row.CopySourceToExisting};var affectedLayers=new HashSet<ObjectId>();foreach(var member in members){var id=db.GetObjectId(false,new Handle(Int64.Parse(member.Handle,NumberStyles.HexNumber,CultureInfo.InvariantCulture)),0);var e=(Entity)tr.GetObject(id,OpenMode.ForRead);if(e.LayerId.IsNull||((LayerTableRecord)tr.GetObject(e.LayerId,OpenMode.ForRead)).IsLocked)throw new InvalidOperationException("Đường nguồn nằm trên Layer khóa.");action.Objects.Add(id);var lid=keep?e.LayerId:destLayer;var actual=(LayerTableRecord)tr.GetObject(lid,OpenMode.ForRead);if(actual.IsDependent||actual.IsLocked)throw new InvalidOperationException("Layer đích bị khóa hoặc phụ thuộc Xref: "+actual.Name);affectedLayers.Add(lid);signature.Add("L|"+actual.Handle+"|"+actual.LinetypeObjectId.Handle+"|"+actual.IsLocked+"|"+actual.IsDependent);if(row.SyncLayer){string prior;if(layerTypes.TryGetValue(lid,out prior)&&!String.Equals(prior,target,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Một Layer được chọn đồng bộ tới nhiều linetype khác nhau: "+actual.Name);layerTypes[lid]=target;}}
                    action.AffectedLayers.AddRange(affectedLayers);int byLayerOthers=0;var shared=new List<string>();if(row.SyncLayer)foreach(ObjectId bid in blocks){var block=(BlockTableRecord)tr.GetObject(bid,OpenMode.ForRead);if(block.IsFromExternalReference||block.IsFromOverlayReference)continue;foreach(ObjectId eid in block){var entity=tr.GetObject(eid,OpenMode.ForRead) as Entity;if(entity!=null&&affectedLayers.Contains(entity.LayerId)&&entity.LinetypeId==db.ByLayerLinetype&&!action.Objects.Contains(eid)){byLayerOthers++;shared.Add(eid.Handle.ToString()+":"+entity.LayerId.Handle);}}}if(row.SyncLayer)signature.Add("A|"+String.Join(",",shared.OrderBy(x=>x,StringComparer.Ordinal)));
                    int sharedTarget=0;var sharedType=new List<string>();if(!create&&row.CopySourceToExisting){var targetId=types[target];foreach(ObjectId bid in blocks){var block=(BlockTableRecord)tr.GetObject(bid,OpenMode.ForRead);if(block.IsFromExternalReference||block.IsFromOverlayReference)continue;foreach(ObjectId eid in block){var entity=tr.GetObject(eid,OpenMode.ForRead) as Entity;if(entity==null)continue;var actual=entity.LinetypeId;if(actual==db.ByLayerLinetype)actual=((LayerTableRecord)tr.GetObject(entity.LayerId,OpenMode.ForRead)).LinetypeObjectId;if(actual==targetId){sharedTarget++;sharedType.Add(eid.Handle.ToString()+":"+entity.LayerId.Handle);}}}signature.Add("R|"+String.Join(",",sharedType.OrderBy(x=>x,StringComparer.Ordinal)));}
                    signature.Add("M|"+source+"|"+target+"|"+layerName+"|"+row.SyncLayer+"|"+row.CopySourceToExisting+"|"+srcDef.Fingerprint+"|"+String.Join(",",members.OrderBy(x=>x.Handle).Select(x=>x.Handle+":"+x.State)));plan.Actions.Add(action);plan.Preview.Add(new BatchPreviewRow{LayerBefore=row.CurrentLayers,LayerAfter=keep?"Giữ Layer từng đường":layerName,TypeBefore=source,TypeAfter=target,TextBefore=srcDef.Text,TextAfter=srcDef.Text,Detail=(create?"Tạo nét mới bằng bản sao nguồn R; ":row.CopySourceToExisting?"GHI ĐÈ nét đích: chữ ["+targetBefore+"] → ["+srcDef.Text+"]; "+sharedTarget+" đối tượng tham chiếu nét đích sẽ thay đổi; ":"Dùng định nghĩa R đích hiện có; ")+(row.SyncLayer?"đồng bộ "+affectedLayers.Count+" Layer, ảnh hưởng thêm "+byLayerOthers+" đối tượng ByLayer (kể cả trong block).":"dòng này không yêu cầu đổi nét Layer; nếu Layer khác nét đích thì ống được gán đè trực tiếp.")+" Số đường: "+members.Count});
                }
                for(int i=0;i<plan.Actions.Count;i++)if(!rows[i].SyncLayer&&plan.Actions[i].AffectedLayers.Any(id=>layerTypes.ContainsKey(id)))plan.Preview[i].Detail+=" LƯU Ý: Layer của dòng này cũng được đồng bộ bởi dòng khác trong cùng đợt.";
                foreach(var target in overwrittenTypes.Keys)if(plan.Actions.Where(a=>String.Equals(a.TargetType,target,StringComparison.OrdinalIgnoreCase)).Select(a=>a.Source).Distinct(StringComparer.OrdinalIgnoreCase).Count()>1)throw new InvalidOperationException("Nhiều nét nguồn cùng dùng nét đích được chọn ghi đè: "+target+". Xử lý riêng từng nhóm.");
                foreach(var pair in layerTypes)plan.LayerTypes.Add(pair.Key,pair.Value);
            }
            plan.Signature=Profile.Hash(String.Join("|",signature));plan.Summary="Ánh xạ "+plan.Actions.Count+" nét mã; "+plan.Actions.Sum(x=>x.Objects.Count)+" đường trực tiếp trong Model/Layout. Không sửa hình học, màu, scale hay width. Không quét Xref/đường trong block. Layer đồng bộ sẽ ảnh hưởng các đối tượng ByLayer khác; xem cột Chi tiết.";return plan;
        }
        public static int Apply(Database db,IEnumerable<LegacyMapRow> rows,LegacyMapPlan reviewed,bool injectFailure=false)
        {
            var current=Inspect(db,rows,reviewed.CatalogState);if(current.Signature!=reviewed.Signature)throw new InvalidOperationException("Nguồn hoặc đích đã thay đổi sau khi xem trước; chưa áp dụng.");using(var tr=db.TransactionManager.StartTransaction())
            {
                var types=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead);var targets=new Dictionary<string,ObjectId>(StringComparer.OrdinalIgnoreCase);foreach(var action in current.Actions){if(targets.ContainsKey(action.TargetType))continue;if(types.Has(action.TargetType))targets[action.TargetType]=types[action.TargetType];else{var source=(LinetypeTableRecord)tr.GetObject(action.SourceId,OpenMode.ForRead);var clone=(LinetypeTableRecord)source.Clone();clone.Name=action.TargetType;if(!types.IsWriteEnabled)types.UpgradeOpen();types.Add(clone);tr.AddNewlyCreatedDBObject(clone,true);targets[action.TargetType]=clone.ObjectId;}}
                foreach(var action in current.Actions.Where(x=>x.CopySourceToExisting))LabelService.RestoreLegacyR(db,tr,action.SourceId,targets[action.TargetType]);
                foreach(var pair in current.LayerTypes){var layer=(LayerTableRecord)tr.GetObject(pair.Key,OpenMode.ForWrite);layer.LinetypeObjectId=targets[pair.Value];}
                int count=0;foreach(var action in current.Actions){var type=targets[action.TargetType];foreach(var id in action.Objects){var e=(Entity)tr.GetObject(id,OpenMode.ForWrite);if(!action.TargetLayer.IsNull)e.LayerId=action.TargetLayer;var layer=(LayerTableRecord)tr.GetObject(e.LayerId,OpenMode.ForRead);e.LinetypeId=layer.LinetypeObjectId==type?db.ByLayerLinetype:type;count++;if(injectFailure)throw new InvalidOperationException("Injected manual mapping rollback.");}}
                tr.Commit();return count;
            }
        }
    }
}
